export type GridBox = {
  id: string;
  position: GridPoint;
  minimumSize?: GridSize;
  collapsed: boolean;
  collapsedContentId?: string;
} & (
  | { kind: "diagram"; contentId: string }
  | { kind: "container"; children: readonly GridBox[]; layout: { collisionPolicy: "push-right"; gap: number } }
